<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {BookOpen,Plus,Users,ArrowRight,X} from '@lucide/vue'
import {auth,loadSession} from '../composables/auth'
import {experience} from '../composables/experience'
import {api} from '../api'
import NotificationBadge from '../components/NotificationBadge.vue'
import {courseNotifications} from '../composables/notifications'
const courses=ref([]),loading=ref(true),error=ref(''),showForm=ref(false),busy=ref(false),form=reactive({code:'',title:'',year:'',semester:'1',classLabel:''})
const props=defineProps({enrolled:Boolean})
const teachingPortal=computed(()=>!props.enrolled && (auth.user.canTeach || auth.user.canCreateCourses))
function taughtPreview(c){return props.enrolled && c.courseRole==='teacher'}
function courseLink(c){return {path:'/courses/'+c.id,query:taughtPreview(c)?{view:'preview'}:{}}}
const visibleCourses=computed(()=>courses.value.filter(c=>teachingPortal.value ? ['teacher','ta'].includes(c.courseRole) : c.courseRole==='student' || taughtPreview(c)))
const roles={teacher:'授課教師',ta:'課程助教',student:'學生'}
async function load(){loading.value=true;error.value='';try{courses.value=await api(props.enrolled?'/courses?studentPortal=true':'/courses')}catch(e){error.value=e.message}finally{loading.value=false}}
async function create(){busy.value=true;error.value='';try{await api('/courses',{method:'POST',body:{code:form.code,title:form.title,classLabel:form.classLabel,termCode:form.year+'-'+form.semester}});Object.assign(form,{code:'',title:'',year:'',semester:'1',classLabel:''});showForm.value=false;await loadSession(true);await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page-heading"><div><h1>{{teachingPortal?'我的授課':'我的修課'}}</h1></div><button v-if="teachingPortal && auth.user.canCreateCourses && !experience.student" class="button primary" @click="showForm=!showForm"><Plus :size="17" />建立課程</button></section><p v-if="error" class="error-box" role="alert">{{error}} <button type="button" class="text-button" :disabled="loading" @click="load">重新載入課程</button></p><section v-if="showForm" class="surface form-surface"><div class="section-title"><h2>建立課程</h2><button class="icon-button" aria-label="關閉建立課程" @click="showForm=false"><X :size="18" /></button></div><form @submit.prevent="create"><fieldset :disabled="busy"><div class="form-grid three"><label>課程代碼<input v-model="form.code" required maxlength="40" /></label><label>課程名稱<input v-model="form.title" required maxlength="200" /></label><label>學年度<input v-model="form.year" type="number" min="1" max="999" required/></label><label>學期<select v-model="form.semester"><option value="1">上學期</option><option value="2">下學期</option><option value="S">暑修</option></select></label><label>班別<input v-model="form.classLabel" maxlength="80"/></label></div><p class="field-hint">建立者成為課程擁有者；進入課程後可安排學員與相關評量。</p><button class="button primary">儲存課程</button></fieldset></form></section><p v-if="loading" class="empty-inline">載入課程中…</p><section v-else-if="!error && !visibleCourses.length" class="surface course-empty"><BookOpen :size="32" /><h2>{{teachingPortal?'目前沒有授課課程':'目前沒有已選修的課程'}}</h2><p>{{teachingPortal?'建立課程或請課程擁有者加入教學團隊。':(auth.user.canTeach?'這裡會顯示你任教的課程，以及你已選修並開放的課程。':'課程開放且你已加入學員名單後，就會出現在這裡。')}}</p></section><div v-else class="course-grid"><article v-for="course in visibleCourses" :key="course.id" class="surface course-card"><div class="course-card-top"><span class="course-emblem"><BookOpen :size="24" /></span><span class="status-badge">{{{draft:'草稿',active:'進行中',archived:'已封存'}[course.status]}}</span></div><span class="eyebrow">{{course.code}} · {{course.termCode}} {{course.classLabel}}</span><h2 :aria-label="course.title">{{course.title}} <NotificationBadge v-if="!taughtPreview(course)" :count="courseNotifications(course.id).total" label="本課未讀通知" /></h2><div v-if="!taughtPreview(course)" class="course-notification-links"><RouterLink v-if="courseNotifications(course.id).materials" :to="'/courses/'+course.id+'?section=resources'">新教材 <NotificationBadge :count="courseNotifications(course.id).materials"/></RouterLink><RouterLink v-if="courseNotifications(course.id).assignments" :to="`/courses/${course.id}?section=assessments`">新測驗／作業 <NotificationBadge :count="courseNotifications(course.id).assignments" label="新測驗與作業" /></RouterLink><RouterLink v-if="courseNotifications(course.id).questions" :to="`/courses/${course.id}?section=questions`">學生新提問 <NotificationBadge :count="courseNotifications(course.id).questions" label="學生新提問" /></RouterLink></div><p class="muted">{{taughtPreview(course)?'學生視角（授課課程）':roles[course.courseRole]}}<span v-if="course.isOwner"> · 課程擁有者</span></p><div class="course-meta"><span><Users :size="15" />{{course.studentCount}} 位學員</span><span>{{course.resourceCount}} 份教材</span></div><p class="field-hint">{{course.quizCount}} 份測驗 · {{course.reportCount}} 份 PDF 作業</p><RouterLink :to="courseLink(course)" class="button primary course-open-link">進入課程 <ArrowRight :size="16" /></RouterLink></article></div></template>
